create table if not exists public.storefront_texts (
 key text primary key,
 source_text text not null,
 es text not null,
 en text not null,
 updated_at timestamptz not null default now()
);
alter table public.storefront_texts enable row level security;
grant select on public.storefront_texts to anon, authenticated;
create policy "Public can read storefront copy" on public.storefront_texts for select to anon, authenticated using (true);
on conflict (key) do nothing;
